<script setup lang="ts">
// Shows one frame generated by examples/docs-previews. The HTML comes from our own renderer, which escapes every text run, so v-html only ever receives markup we produced.
import { computed } from 'vue';
import previews from '../generated/previews.json';

type PreviewEntry = {
  title: string;
  caption?: string;
  columns: number;
  html: string;
  text: string;
};

const props = defineProps<{ id: string }>();

const entries = previews as Record<string, PreviewEntry>;
const entry = computed(() => entries[props.id]);
</script>

<template>
  <figure v-if="entry" class="terminal-preview">
    <div class="terminal-window" :style="{ '--preview-columns': entry.columns }">
      <div class="terminal-bar" aria-hidden="true">
        <span class="dot dot-red" />
        <span class="dot dot-amber" />
        <span class="dot dot-green" />
        <span class="terminal-title">{{ entry.title }}</span>
      </div>
      <pre class="terminal-screen" v-html="entry.html" />
    </div>
    <figcaption v-if="entry.caption">{{ entry.caption }}</figcaption>
  </figure>
  <p v-else class="terminal-preview-missing">Preview "{{ id }}" is not generated. Run npm run generate in examples/docs-previews.</p>
</template>

